@Composable
fun OverlaysScreen(
  modifier: Modifier = Modifier,
  onNavigateToHome: () -> Unit = {},
  onNavigateToActions: () -> Unit = {},
  onNavigateToInputs: () -> Unit = {},
  onNavigateToOverlays: () -> Unit = {},
  onNavigateToFabs: () -> Unit = {},
  onNavigateToCollections: () -> Unit = {},
  onNavigateToFeedback: () -> Unit = {},
) {
  var showSheet by remember { mutableStateOf(false) }
  var showDialog by remember { mutableStateOf(false) }
  var showMenu by remember { mutableStateOf(false) }
  var showMenuVibrant by remember { mutableStateOf(false) }
  var showDateDocked by remember { mutableStateOf(false) }
  var showDateModal by remember { mutableStateOf(false) }
  var showDateInput by remember { mutableStateOf(false) }
  var showDateRange by remember { mutableStateOf(false) }
  var showDateFull by remember { mutableStateOf(false) }
  var showTimeDial by remember { mutableStateOf(false) }
  var showTimeInput by remember { mutableStateOf(false) }
  var showDialogFull by remember { mutableStateOf(false) }
  val windowSizeClass = currentWindowAdaptiveInfoV2().windowSizeClass
  val atLeastMedium =
    windowSizeClass.isWidthAtLeastBreakpoint(WindowSizeClass.WIDTH_DP_MEDIUM_LOWER_BOUND)
  val atLeastExpanded =
    windowSizeClass.isWidthAtLeastBreakpoint(WindowSizeClass.WIDTH_DP_EXPANDED_LOWER_BOUND)
  Row(modifier = modifier) {
    if (atLeastMedium && !atLeastExpanded) {
      WideNavigationRail(state = rememberWideNavigationRailState()) {
        WideNavigationRailItem(
          railExpanded = false,
          selected = false,
          onClick = { onNavigateToHome() },
          icon = { Icon(painterResource(R.drawable.home), contentDescription = null) },
          label = { Text("Home") },
        )
        WideNavigationRailItem(
          railExpanded = false,
          selected = false,
          onClick = { onNavigateToActions() },
          icon = { Icon(painterResource(R.drawable.touch_app), contentDescription = null) },
          label = { Text("Actions") },
        )
        WideNavigationRailItem(
          railExpanded = false,
          selected = false,
          onClick = { onNavigateToInputs() },
          icon = { Icon(painterResource(R.drawable.tune), contentDescription = null) },
          label = { Text("Inputs") },
        )
        WideNavigationRailItem(
          railExpanded = false,
          selected = true,
          onClick = { onNavigateToOverlays() },
          icon = { Icon(painterResource(R.drawable.layers), contentDescription = null) },
          label = { Text("Overlays") },
        )
      }
    } else if (atLeastExpanded) {
      WideNavigationRail(
        state = rememberWideNavigationRailState(WideNavigationRailValue.Expanded),
      ) {
        WideNavigationRailItem(
          railExpanded = true,
          selected = false,
          onClick = { onNavigateToHome() },
          icon = { Icon(painterResource(R.drawable.home), contentDescription = null) },
          label = { Text("Home") },
